// ===== CONSTANTS & HELPERS =====
export const WA = '62882009466583'

export function buildWaLink(productName: string, variantName: string, price: string): string {
  const msg = encodeURIComponent(
    `Halo Kak, saya mau order:\n\n📦 *${productName}*\n✅ Paket: ${variantName}\n💰 Harga: ${price}\n\nMohon konfirmasi & info selanjutnya. Terima kasih! 🙏`
  )
  return `https://wa.me/${WA}?text=${msg}`
}

